package com.example;

public class Array3 {

	public static void main(String[] args) {
		int a[][]= {{10,20},{30,40}};
		for (int i=0;i<a.length;i++)
		{
			for(int j=0;j<a[i].length;i++) {
				System.out.print(a[i][j]+"\t");
		}
		System.out.println();
		// TODO Auto-generated method stub
		}
	}

}
